 const session=ref(''),active=ref('系统首页'),detail=ref<{kind:string;id:string}|null>(null),history=ref<{page:string;detail:{kind:string;id:string}|null}[]>([]),drawer=ref(false),filters=reactive<Record<string,Filter>>({}),chosen=ref<Record<string,unknown>[]>([]),busy=ref(false),error=ref(''),contextId=ref(''),faceSource=ref(''),faceReference=ref(0),similarity=ref(0),statRows=ref<ReturnType<typeof statistics>>([]),statSelected=ref<string[]>([]),resultTab=ref('电围'),mapSelected=ref<string[]>([]),mapTrajectory=ref(false),selectedDataset=ref(''),operands=ref<string[]>([]),expression=ref('A ∩ B'),setResult=ref<string[]>([]),setHasResult=ref(false),httpMenus=ref<string[]>([]),permissions=ref<string[]>([]),features=ref<{featureCode:string;enabled:boolean;pendingReason?:string|null}[]>([]),remoteIntent=ref<RemoteIntent|null>(null);
 const currentUser=computed(()=>apiMode==='http'&&remote.me?{id:remote.me.user.userId,name:remote.me.user.displayName,account:remote.me.user.loginName,role:remote.me.roleIds[0]||'',enabled:remote.me.user.status==='ACTIVE',password:undefined}:db.users.find(u=>u.id===session.value));
