 function currentCaptureResults(){const type=({'围栏检索':'电围','车牌检索':'车牌','MAC检索':'MAC','人像检索':'人像'} as Record<string,string>)[active.value]||(active.value==='地图研判'&&f.value.type!=='综合'?String(f.value.type||'电围'):undefined);const task=detail.value?.kind==='analysis'?db.analysis[active.value]?.find(t=>t.id===detail.value?.id):undefined;const source=task?analysisResults(task,resultTab.value,active.value).flatMap(r=>r.captures):filterRows(captureRows(type),f.value,{site:r=>r.site,start:r=>r.time,end:r=>r.time,target:r=>r.target,imei:r=>r.imei});return [...new Map(source.map(row=>[row.id,row])).values()];}
