 function formLibrary(id?:string){if(apiMode==='http'){void remoteForm(()=>openLibrary(formHost,id));return;}const old=db.libraries.find(r=>r.id===id);showForm(old?'编辑人员库':'新增人员库',[named('name','库名',true),options('category','分类',['重点人员','常驻人员','自建库'])],old||{name:'',category:'自建库'},m=>{if(db.libraries.some(r=>r.name===text(m,'name')&&r.id!==id))throw new Error('库名已存在');const r={id:id||uid(),name:text(m,'name'),category:text(m,'category'),people:old?.people||[]};if(old)Object.assign(old,r);else db.libraries.push(r);modal.visible=false;commit('人员库已保存');});bindRemote({kind:'library',id});}
 function formPerson(libId:string,id?:string){if(apiMode==='http'){void remoteForm(()=>openPerson(formHost,libId,id));return;}const old=db.people.find(r=>r.id===id),lib=db.libraries.find(r=>r.id===libId);if(!lib)return;showForm(old?'编辑人员':'新增人员',[named('name','姓名',true),options('sex','性别',['男','女','未知']),named('ethnic','民族'),named('phone','手机号码'),named('identity','身份证号码'),named('target','IMSI / 特征码',true),named('resident','常驻地区'),named('landing','疑似落脚点'),named('appearance','外貌特征')],old||{name:'',sex:'男'},m=>{const p:Person={id:id||uid(),name:text(m,'name'),sex:text(m,'sex'),ethnic:text(m,'ethnic'),phone:text(m,'phone'),identity:text(m,'identity'),target:text(m,'target'),resident:text(m,'resident'),landing:text(m,'landing'),appearance:text(m,'appearance'),image:old?.image||db.people[0]?.image||''};if(old)Object.assign(old,p);else{db.people.push(p);lib.people.push(p.id);}modal.visible=false;commit('人员信息已保存');});bindRemote({kind:'person',id,libraryId:libId});}
 function formWatch(id?:string,rows:Capture[]=[]){if(apiMode==='http'){void remoteForm(()=>openWatch(formHost,db,id,rows));return;}const old=db.watches.find(r=>r.id===id);showForm(old?'编辑布控信息':'新增布控',[named('name','布控名称',true),...intervalFields,options('type','数据类型',[...dataTypes]),named('target','目标标识',true),{key:'person',label:'重点人员',options:db.people.map(p=>({label:p.name,value:p.id}))},options('channel','通知方式',['短信','邮件','平台']),named('recipient','通知对象',true)],old||{name:'',start:'2026-10-08T08:00',end:'2026-10-09T18:00',type:rows[0]?.type||'电围',target:[...new Set(rows.map(r=>r.target))].join(','),person:rows[0]?.person||'',channel:'短信',recipient:'13800000000'},m=>{timeCheck(m);const r:Watch={id:id||uid(),name:text(m,'name'),account:old?.account||currentUser.value?.account||'',start:text(m,'start'),end:text(m,'end'),type:text(m,'type'),target:text(m,'target'),person:text(m,'person'),channel:text(m,'channel'),recipient:text(m,'recipient'),status:old?.status||'运行中',hits:old?.hits||[]};if(old)Object.assign(old,r);else db.watches.push(r);modal.visible=false;navigate('综合布控');commit('布控任务已保存');});bindRemote({kind:'watch',id,rows});}
