 async function remove(scope:keyof Database,ids=chosen.value.map(r=>String(r.id))){if(!ids.length){ElMessage.warning('请先勾选数据');return;}if(!await confirm('确认删除所选 '+ids.length+' 项？'))return;try{if(apiMode==='http'){if(!['sites','devices','libraries','datasets','watches','configs','reports','notifications','roles','users'].includes(scope))throw new Error('该列表未定义批量删除接口');const result=await deleteRemote(scope as 'sites'|'devices'|'libraries'|'datasets'|'watches'|'configs'|'reports'|'notifications'|'roles'|'users',ids);chosen.value=[];await reload();ElMessage[result.failureCount?'warning':'success'](`删除成功 ${result.successCount} 项，失败 ${result.failureCount} 项`);return;}const all=db[scope];if(!Array.isArray(all))return;const rows=all.filter(r=>ids.includes(r.id));if(scope==='roles'&&db.users.some(u=>ids.includes(u.role)))throw new Error('角色仍有用户使用，不能删除');if(scope==='users'&&db.users.some(u=>ids.includes(u.id)&&u.enabled))throw new Error('请先禁用用户再删除');if(scope==='sites'&&db.devices.some(d=>rows.some(s=>s.id===db.sites.find(x=>x.name===d.site)?.id)))throw new Error('场所仍有设备，不能删除');Object.assign(db,{[scope]:all.filter(r=>!ids.includes(r.id))});chosen.value=[];commit('所选内容已删除');}catch(e){ElMessage.error(e instanceof Error?e.message:String(e));}}
